fn is_amount(s: Str) -> Bool {
  if s.len() == 0 {
    return false
  }
  if not s.chars().all(fn(c) => "0123456789".contains(c)) {
    return false
  }
  return s.to_int().unwrap_or(0) > 0
}

fn balance_of(m: Map[Str, Int], name: Str) -> Result[Int, Str] {
  return m.get(name).ok_or("unknown {name}")
}

fn apply_op(m: Map[Str, Int], op: Str) -> Result[Map[Str, Int], Str] {
  let parts = op.split(" ")
  let verb = parts.get_or(0, "")
  if verb == "open" and parts.len() == 2 {
    let name = parts.get_or(1, "")
    if name.is_empty() {
      return Err("bad op")
    }
    if m.has(name) {
      return Err("exists {name}")
    }
    return Ok(m.set(name, 0))
  }
  if verb == "dep" or verb == "wd" {
    if parts.len() != 3 {
      return Err("bad op")
    }
    let name = parts.get_or(1, "")
    let amount = parts.get_or(2, "")
    if name.is_empty() or not is_amount(amount) {
      return Err("bad op")
    }
    let n = amount.to_int().unwrap_or(0)
    let bal = balance_of(m, name)?
    if verb == "dep" {
      return Ok(m.set(name, bal + n))
    }
    if bal < n {
      return Err("insufficient {name}")
    }
    return Ok(m.set(name, bal - n))
  }
  if verb == "move" {
    if parts.len() != 4 {
      return Err("bad op")
    }
    let a_name = parts.get_or(1, "")
    let b_name = parts.get_or(2, "")
    let amount = parts.get_or(3, "")
    if a_name.is_empty() or b_name.is_empty() or not is_amount(amount) {
      return Err("bad op")
    }
    let n = amount.to_int().unwrap_or(0)
    let a_bal = balance_of(m, a_name)?
    let _b_bal = balance_of(m, b_name)?
    if a_bal < n {
      return Err("insufficient {a_name}")
    }
    let m1 = m.set(a_name, a_bal - n)
    let b_now = balance_of(m1, b_name)?
    return Ok(m1.set(b_name, b_now + n))
  }
  return Err("bad op")
}

pub fn ledger(ops: List[Str]) -> Result[Map[Str, Int], Str] {
  let empty: Map[Str, Int] = Map {}
  var m: Map[Str, Int] = empty
  for op in ops {
    m = apply_op(m, op)?
  }
  return Ok(m)
}
